<script setup>import {onMounted,ref} from 'vue';import {get,pct} from '../api/client';import DataTable from '../components/DataTable.vue';const runs=ref([]),selected=ref(),data=ref({groups:[],detail:[]});async function load(){data.value=await get(`/verifications/${selected.value}`)}onMounted(async()=>{runs.value=await get('/verifications');if(runs.value.length){selected.value=runs.value[0].id;load()}});const groups=[{label:'TopN',key:'top_n'},{label:'已验证',key:'verified_count'},{label:'上涨数',key:'up_count'},{label:'上涨比例',key:'up_rate',format:pct},{label:'平均收益',key:'avg_return',format:pct},{label:'超额收益',key:'excess_return',format:pct}];const detail=[{label:'排名',key:'ranking'},{label:'代码',key:'stock_code'},{label:'名称',key:'stock_name'},{label:'评分',key:'score'},{label:'实际收益',key:'actual_return',format:pct},{label:'超额收益',key:'market_excess',format:pct}]</script><template><div v-if="!runs.length" class="empty">尚无正式验证。下一交易日收盘行情入库后自动生成。</div><template v-else><select v-model="selected" @change="load"><option v-for="r in runs" :value="r.id">{{r.base_date}} → {{r.actual_trade_date}}</option></select><div class="section"><h2>TopN 验证</h2><DataTable :columns="groups" :rows="data.groups"/></div><div class="section"><h2>验证明细</h2><DataTable :columns="detail" :rows="data.detail"/></div></template></template>
